import { z } from "zod";
import type { IntakeContext, OrderInput } from "./types";

function matchesEntire(pattern: RegExp, value: string): boolean {
  return pattern.exec(value)?.[0] === value;
}

const identifier = z.string().refine((value) =>
  matchesEntire(/^[A-Za-z0-9_-]{1,64}$/, value),
);

function isCalendarDate(year: number, month: number, day: number): boolean {
  if (
    !Number.isInteger(year) ||
    !Number.isInteger(month) ||
    !Number.isInteger(day) ||
    year < 2000 ||
    year > 2099 ||
    month < 1 ||
    month > 12 ||
    day < 1
  ) {
    return false;
  }
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day <= days[month - 1];
}

function isCanonicalDate(value: string): boolean {
  if (!matchesEntire(/^20\d{2}-\d{2}-\d{2}$/, value)) return false;
  const [year, month, day] = value.split("-").map(Number);
  return isCalendarDate(year, month, day);
}

function canonicalDate(year: number, month: number, day: number): string {
  return `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(
    2,
    "0",
  )}`;
}

function decimalToCents(value: unknown): number | undefined {
  if (typeof value !== "string") return undefined;
  const match = /^(0|[1-9]\d*)(?:\.(\d{1,2}))?$/.exec(value);
  if (match === null) return undefined;

  const dollarsText = match[1];
  if (dollarsText.length > 5) return undefined;

  const dollars = Number(dollarsText);
  const centsText = (match[2] ?? "").padEnd(2, "0");
  const cents = dollars * 100 + (centsText === "" ? 0 : Number(centsText));
  return cents >= 1 && cents <= 1_000_000 ? cents : undefined;
}

function parseVersionTwoDate(value: unknown): string | undefined {
  if (
    value === null ||
    typeof value !== "object" ||
    Array.isArray(value)
  ) {
    return undefined;
  }

  const date = value as Record<string, unknown>;
  const { year, month, day } = date;
  if (
    typeof year !== "number" ||
    typeof month !== "number" ||
    typeof day !== "number" ||
    !isCalendarDate(year, month, day)
  ) {
    return undefined;
  }

  return canonicalDate(year, month, day);
}

const versionOne = z.object({
  formatVersion: z.literal(1).optional(),
  id: identifier,
  customerId: identifier,
  amountCents: z.number().int().min(1).max(1_000_000),
  shipOn: z.string().refine(isCanonicalDate),
});

const versionTwoBase = z.object({
  formatVersion: z.literal(2),
  id: identifier,
  customerId: identifier,
});

export function isOrderId(value: unknown): value is string {
  return identifier.safeParse(value).success;
}

export function parseOrder(
  value: unknown,
  context: IntakeContext,
): OrderInput | undefined {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    return undefined;
  }

  const candidate = value as Record<string, unknown>;
  const selectedVersion = candidate.formatVersion;

  if (selectedVersion === undefined || selectedVersion === 1) {
    const parsed = versionOne.safeParse(value);
    if (!parsed.success) return undefined;
    return {
      id: parsed.data.id,
      customerId: parsed.data.customerId,
      amountCents: parsed.data.amountCents,
      shipOn: parsed.data.shipOn,
    };
  }

  if (selectedVersion !== 2) return undefined;

  const parsed = versionTwoBase.safeParse(value);
  if (!parsed.success) return undefined;

  if (
    candidate.amount === null ||
    typeof candidate.amount !== "object" ||
    Array.isArray(candidate.amount)
  ) {
    return undefined;
  }

  const amount = candidate.amount as Record<string, unknown>;
  const amountCents = decimalToCents(amount.decimal);
  if (amountCents === undefined) return undefined;
  if (amount.currency !== undefined && amount.currency !== "USD") {
    return undefined;
  }

  const shipOn =
    Object.prototype.hasOwnProperty.call(candidate, "shipOn")
      ? parseVersionTwoDate(candidate.shipOn)
      : context.receivedOn;
  if (shipOn === undefined) return undefined;

  return {
    id: parsed.data.id,
    customerId: parsed.data.customerId,
    amountCents,
    shipOn,
  };
}
